import { expect, expectStatus, test } from "../../fixtures";

// Held as test.fixme() per QA lead (2026-11-02): the endpoint is being rewritten under PLAT-412.
test.fixme("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange: a member's vendor that has been submitted and is in review
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview();

  // Act: the member changes the vendor's contact email
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
});
